        "A": "Player X's team puts the ball back into play.",
        "B": "The opposing team puts the ball back into play.",
        "C": "The opposing team receives a free throw.",
        "D": "The opposing captain puts the ball back into play."
      },
      "answer": "A"
    },
    {
      "n": 2,
      "topic": "Scoring Timing",
      "stem": "Team Blue is winning 15-10. With 45 seconds left in the final period, Team Blue sinks the ball in the Tarn on a rebound off the rim (normally 3 points). How many points do they score?",
      "options": {
        "A": "0 points",
        "B": "2 points",
        "C": "3 points",
        "D": "6 points"
      },
      "answer": "C"
    },
    {
      "n": 3,
      "topic": "Foul Accumulation",
      "stem": "The Warden on Team Red commits their third foul of the match. What happens next?",
      "options": {
        "A": "The Warden is sent off.",
        "B": "Team Red's captain is sent off.",
        "C": "The opposing team gets a free throw and possession.",
        "D": "Team Red must play one player short until they score."
      },
      "answer": "B"
    },
    {
      "n": 4,
      "topic": "Possession Penalties",
      "stem": "A player freezes under pressure and holds the ball for 8 seconds. How does the referee restart play?",
      "options": {
        "A": "The opposing team gets possession.",
        "B": "The opposing team gets a free throw, but the holding player's team keeps possession.",
        "C": "The holding player is sent to a 2-minute sit-out.",
        "D": "The holding player's captain receives a foul."
      },
      "answer": "B"
    },
    {
      "n": 5,
      "topic": "League Standings",
      "stem": "A match ends in a tie and goes to Warden throws. Team A misses first, losing the tiebreak to Team B. How many league table points does Team A receive for this match?",
      "options": {
        "A": "0 points",
        "B": "1 point",
        "C": "2 points",
        "D": "3 points"
      },
      "answer": "C"
    },
    {
      "n": 6,
      "topic": "Challenges",
      "stem": "A coach challenges a foul call, but the video official upholds the referee's original decision. What is the consequence?",
      "options": {
        "A": "The team loses a timeout.",
        "B": "The challenging team loses 1 point from their match score.",
        "C": "The challenging team's captain receives a foul.",
        "D": "The opposing team is awarded a free throw."
      },
      "answer": "B"
    },
    {
      "n": 7,
      "topic": "Officials",
      "stem": "A controversial play happens entirely inside the Shallows. The ring referee calls a foul, but the video official communicates that it was a clean play. Whose call is applied?",
      "options": {
        "A": "The video official, because video review is final.",
        "B": "The ring referee, because their call overrides inside the Shallows.",
        "C": "The video official, unless the challenging team intervenes.",
        "D": "The ring referee, but they are charged 1 point."
      },
      "answer": "B"
    },
    {
      "n": 8,
      "topic": "Timing",
      "stem": "During the first period, a player is injured, and play is delayed for 4 minutes. How is this lost time handled?",
      "options": {
        "A": "The clock stops during the injury, so no time needs to be added.",
        "B": "4 minutes are added to the end of the first period.",
        "C": "4 minutes are added to the end of the third period.",
        "D": "Lost time is ignored and not added to any period."
      },
      "answer": "C"
    },
    {
      "n": 9,
      "topic": "Scoring (Own Goals)",
      "stem": "A player accidentally deflects the ball into their own Tarn. Team Red was the last team to touch the ball before the own goal. What is the outcome?",
      "options": {
        "A": "Team Blue scores 2 points.",
        "B": "Team Blue scores 3 points.",
        "C": "No points are scored; Team Red retains possession.",
        "D": "No points are scored; Team Blue gains possession."
      },
      "answer": "D"
    },
    {
      "n": 10,
      "topic": "Scoring Rules",
      "stem": "Team A has a dominant run and takes a 16-point lead over Team B. What immediate restriction applies to Team A?",
      "options": {
        "A": "Their Warden is no longer allowed to pass.",
        "B": "They must play one player short until their lead falls below 10 points.",
        "C": "They are not allowed to make substitutions.",
        "D": "Any goals they score are only worth 1 point."
      },
      "answer": "B"
    }
  ]
}
